<?php use yii\helpers\Html;$this->title='Document Logs';$types=['IAR','RIS','ICS','PAR','Stock Card'];?><div class="toolbar"><form><select name="type" onchange="this.form.submit()"><option value="">All document types</option><?php foreach($types as $t):?><option <?=$type===$t?'selected':''?>><?=Html::encode($t)?></option><?php endforeach?></select></form><p><?=number_format((int)\common\models\DocumentLog::find()->count())?> imported log entries</p></div><section class="panel tablepanel"><div class="panelhead"><h3><?=count($rows)?> records shown</h3></div><div class="scroll"><table><thead><tr><th>Type</th><th>Reference</th><th>Date</th><th>Stock / Property No.</th><th>Description</th><th>Qty</th><th>Status</th><th>Office</th><th>Recipient</th><th>Action</th></tr></thead><tbody><?php foreach($rows as $r):?><tr><?php foreach(['document_type','reference_no','date','property_number','description','quantity','status','office','party'] as $k):?><td><?=Html::encode($r->$k)?></td><?php endforeach?><td><?=Html::a('View',['/forms/index','type'=>$r->document_type,'ref'=>$r->reference_no],['class'=>'btn','style'=>'white-space:nowrap;padding:7px 12px'])?></td></tr><?php endforeach?></tbody></table></div></section>
